//! Independent wire vectors: literal headers and literal sample octets, never
//! generated by the encoder under test. Values deliberately distinguish fields.
use gigpies::{remote::*, transport::*};

fn hex(s: &str) -> Vec<u8> {
    s.split_whitespace()
        .map(|v| u8::from_str_radix(v, 16).unwrap())
        .collect()
}
fn gpa_pcm() -> Vec<u8> {
    let mut b = hex("47 50 41 31 01 01 00 01 00 30 00 00 01 02 03 04
        01 02 03 04 05 06 07 08 00 00 00 00 00 00 00 60
        00 00 00 02 00 00 bb 80 00 00 00 00 00 00 00 00");
    for _ in 0..12 {
        b.extend(hex("80 00 00 7f ff ff ff ff ff 00 00 01"));
    }
    b
}
fn gpa_wet() -> Vec<u8> {
    let mut b = hex("47 50 41 31 02 03 00 01 00 30 00 00 01 02 03 04
        01 02 03 04 05 06 07 08 00 00 00 00 00 00 00 60
        00 00 00 02 00 00 bb 80 00 00 03 00 00 00 00 00");
    for _ in 0..12 {
        b.extend(hex("c1 80 00 00 41 80 00 00 80 00 00 00 3f 00 00 00"));
    }
    b
}
fn gpa_send() -> Vec<u8> {
    let mut b = hex("47 50 41 31 02 02 00 01 00 30 00 00 01 02 03 04
        01 02 03 04 05 06 07 08 00 00 00 00 00 00 00 60
        00 00 00 02 00 00 bb 80 00 00 00 00 00 00 00 00");
    for _ in 0..12 {
        b.extend(hex("c1 80 00 00 41 80 00 00 80 00 00 00 3f 00 00 00"));
    }
    b
}
fn descriptor() -> BrainMediaDescriptor {
    BrainMediaDescriptor {
        contract: "GP15-media".into(),
        version: 1,
        session: 1,
        stagebox_epoch: 2,
        brain_epoch: 3,
        stagebox_map: 4,
        brain_map: 5,
        generation: 99,
        selection_generation: 6,
        hold_generation: 7,
        sample_rate: 48000,
        frames: 48,
        talkback: true,
        monitor: true,
    }
}
fn gba(role: BrainMediaRole) -> Vec<u8> {
    let mut b = hex("47 42 41 31 01 00 00 00
        00 00 00 00 00 00 00 01 00 00 00 00 00 00 00 02
        00 00 00 00 00 00 00 03 00 00 00 00 00 00 00 04
        00 00 00 00 00 00 00 05 00 00 00 00 00 00 00 07
        00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 07
        00 00 00 00 00 00 00 60");
    if role == BrainMediaRole::Monitor {
        b[4] = 2;
        b[55] = 6;
        b[63] = 6;
        b[71] = 0;
    }
    for _ in 0..24 * role.channels() {
        b.extend(hex("3e 80 00 00 be 80 00 00"));
    }
    b
}
#[test]
fn independent_gpa_vectors_encode_and_decode() {
    for (b, encoding, role, delay) in [
        (gpa_pcm(), Encoding::Pcm24, Role::Analysis, 0),
        (gpa_send(), Encoding::Float32, Role::FxSend, 0),
        (gpa_wet(), Encoding::Float32, Role::WetReturn, 768),
    ] {
        let expected = StreamSpec {
            session: 0x0102030405060708,
            stream: 0x01020304,
            first_channel: 0,
            channels: 1,
            frames: 48,
            encoding,
            role,
            delay_frames: delay,
        };
        let p = Packet::parse(&b).unwrap();
        assert_eq!(p.spec(), expected);
        assert_eq!(p.source_frame(), 96);
        assert_eq!(p.sequence(), 2);
        let mut out = [0; MAX_DATAGRAM];
        let n = if encoding == Encoding::Pcm24 {
            let data: Vec<_> = (0..48).map(|i| [-8388608, 8388607, -1, 1][i % 4]).collect();
            for (i, &s) in data.iter().enumerate() {
                assert_eq!(p.pcm(i).unwrap(), s);
            }
            expected.encode_pcm(96, 2, &data, &mut out).unwrap()
        } else {
            let data: Vec<_> = (0..48).map(|i| [-16f32, 16., -0., 0.5][i % 4]).collect();
            for (i, &s) in data.iter().enumerate() {
                assert_eq!((p.sample(i).unwrap() as f32).to_bits(), s.to_bits());
            }
            expected.encode_float(96, 2, &data, &mut out).unwrap()
        };
        assert_eq!(&out[..n], b);
        for n in 0..b.len() {
            assert!(Packet::parse(&b[..n]).is_err());
        }
        let mut padded = b.clone();
        padded.push(0);
        assert!(Packet::parse(&padded).is_err());
    }
}
#[test]
fn independent_gpa_header_refusals_and_legacy_sequence_origin() {
    for good in [gpa_pcm(), gpa_send(), gpa_wet()] {
        for offset in [0, 3, 4, 5, 6, 8, 10, 36, 40, 44, 45, 46, 47] {
            let mut bad = good.clone();
            bad[offset] = 0xff;
            assert!(Packet::parse(&bad).is_err(), "offset {offset}");
        }
        for range in [6..8, 8..10, 12..16, 16..24] {
            let mut bad = good.clone();
            bad[range].fill(0);
            assert!(Packet::parse(&bad).is_err());
        }
        let mut unaligned = good.clone();
        unaligned[31] = 97;
        assert_eq!(Packet::parse(&unaligned).unwrap_err(), Error::Timeline);
        // The shared parser permits an arbitrary negotiated sequence origin.
        // The selected producer derives it from frames; this is not a new wire version.
        let mut legacy = good;
        legacy[32..36].copy_from_slice(&1234u32.to_be_bytes());
        let packet = Packet::parse(&legacy).unwrap();
        let mut queue = JitterBuffer::new(packet.spec(), 96, 1234, 32).unwrap();
        queue.insert(packet).unwrap();
    }
}
#[test]
fn independent_gba_vectors_and_identity_boundaries() {
    for role in [BrainMediaRole::Talkback, BrainMediaRole::Monitor] {
        let b = gba(role);
        let d = descriptor();
        let p = BrainPacket::decode(&b, &d, role).unwrap();
        assert_eq!(p.frame, 96);
        assert_eq!(p.samples.len(), 48 * role.channels());
        for (i, s) in p.samples.iter().enumerate() {
            assert_eq!(*s, if i % 2 == 0 { 0.25 } else { -0.25 });
        }
        assert_eq!(p.encode().unwrap(), b);
        for n in 0..b.len() {
            assert!(BrainPacket::decode(&b[..n], &d, role).is_err());
        }
        for offset in [0, 4, 5, 6, 7, 15, 23, 31, 39, 47, 55, 63, 71] {
            let mut bad = b.clone();
            bad[offset] ^= 0xff;
            assert!(
                BrainPacket::decode(&bad, &d, role).is_err(),
                "offset {offset}"
            );
        }
        for bits in [0x7fc00000u32, 0x7f800000, 0xff800000] {
            let mut bad = b.clone();
            bad[80..84].copy_from_slice(&bits.to_be_bytes());
            assert!(BrainPacket::decode(&bad, &d, role).is_err());
        }
        let mut bad = b.clone();
        bad[72..80].copy_from_slice(&(u64::MAX / 48 * 48).to_be_bytes());
        assert!(BrainPacket::decode(&bad, &d, role).is_err());
        let mut disabled = d.clone();
        disabled.talkback = false;
        disabled.monitor = false;
        assert!(BrainPacket::decode(&b, &disabled, role).is_err());
    }
}
#[test]
fn wet_deadline_equality_wrap_and_exhaustion() {
    let b = gpa_wet();
    let p = Packet::parse(&b).unwrap();
    let mut q = JitterBuffer::new(p.spec(), 96, 2, 32).unwrap();
    assert_eq!(q.insert_wet_at(p, 864), Err(Error::Late));
    let storage = q.prepared_storage();
    assert!(storage.heap_bytes > 32 * MAX_DATAGRAM);
    assert_eq!(
        storage.total_bytes,
        storage.inline_bytes + storage.heap_bytes
    );
    q.insert_wet_at(p, 863).unwrap();
    assert_eq!(q.insert_wet_at(p, 863), Err(Error::Duplicate));
    let spec = p.spec();
    let first = u64::from(u32::MAX) * 48;
    let mut q = JitterBuffer::new(spec, first, u32::MAX, 32).unwrap();
    for (frame, seq) in [(first, u32::MAX), (first + 48, 0)] {
        let mut out = [0; MAX_DATAGRAM];
        let n = spec.encode_float(frame, seq, &[0.; 48], &mut out).unwrap();
        q.insert_wet_at(Packet::parse(&out[..n]).unwrap(), frame)
            .unwrap();
        assert!(q.pop(&mut out).unwrap().is_some());
    }
    let mut out = [0; MAX_DATAGRAM];
    assert_eq!(
        spec.encode_float(u64::MAX / 48 * 48, 0, &[0.; 48], &mut out),
        Err(Error::Timeline)
    );
    for bits in [0x7fc00000u32, 0x7f800000, 0xff800000, 0x41800001] {
        let mut bad = b.clone();
        bad[48..52].copy_from_slice(&bits.to_be_bytes());
        assert_eq!(Packet::parse(&bad).unwrap_err(), Error::Sample);
    }
}
#[test]
fn checked_resources_and_negotiated_layouts() {
    for inputs in [16, 32, 48] {
        let ids: Vec<_> = (0..inputs).map(|n| format!("input{}", n + 1)).collect();
        for limit in [1232, 1152, 1008] {
            let groups = grouped_streams(MediaRole::Analysis, &ids, 48, 0, 1, limit).unwrap();
            assert_eq!(
                groups.iter().map(|s| s.channel_ids.len()).sum::<usize>(),
                inputs
            );
            for stream in groups {
                assert!(stream.spec(1).unwrap().packet_bytes() <= limit);
            }
        }
        let budget = AudioPayloadBudget::checked(inputs, 8, 8).unwrap();
        assert_eq!(budget.recorder, inputs * 98304);
        assert_eq!(budget.analysis, inputs * 12288);
        assert_eq!(budget.fx_handoffs, 49152);
        assert_eq!(budget.packet_windows, 315392);
        assert_eq!(budget.asrc_rings, 98304);
        // Two mono and two stereo four-block queues, across both nodes.
        assert_eq!(budget.duplex_handoffs, 1536 + 1536 + 3072 + 3072);
    }
    let b = AudioPayloadBudget::checked(16, 8, 8).unwrap();
    assert_eq!(b.total, 2_241_536);
    for (n, c, g) in [
        (0, 8, 8),
        (16, 0, 8),
        (16, 257, 8),
        (16, 8, 0),
        (usize::MAX, 8, 8),
        (16, 8, usize::MAX),
        (683, 8, 8),
    ] {
        assert!(AudioPayloadBudget::checked(n, c, g).is_err());
    }
    assert!(PreparedStorage::checked(usize::MAX, 1).is_err());
    let storage = PreparedStorage::checked(64, 128).unwrap();
    assert_eq!(storage.checked_add(storage).unwrap().total_bytes, 384);
    assert!(
        storage
            .checked_add(PreparedStorage::checked(0, usize::MAX).unwrap())
            .is_err()
    );
    let ids = vec!["left".into(), "right".into()];
    assert!(grouped_streams(MediaRole::FxSend, &ids, 48, 0, 1, 239).is_err());
    assert!(grouped_streams(MediaRole::FxSend, &ids, 48, 0, u32::MAX, 240).is_err());
    let mut specs = vec![
        StreamSpec {
            session: 1,
            stream: 1,
            first_channel: 0,
            channels: 1,
            frames: 48,
            encoding: Encoding::Pcm24,
            role: Role::Analysis,
            delay_frames: 0,
        },
        StreamSpec {
            session: 1,
            stream: 2,
            first_channel: 1,
            channels: 1,
            frames: 48,
            encoding: Encoding::Pcm24,
            role: Role::Analysis,
            delay_frames: 0,
        },
    ];
    validate_session(&specs).unwrap();
    specs[1].first_channel = 0;
    assert!(validate_session(&specs).is_err());
    specs[1].first_channel = 2;
    assert!(validate_session(&specs).is_err());
}

#[test]
fn inline_datagrams_reject_oversize_and_have_no_destructor() {
    assert!(!std::mem::needs_drop::<MediaDatagram>());
    for n in [1, 272, 464, 1232] {
        let bytes = vec![0x5a; n];
        let p = MediaDatagram::copy_from(&bytes).unwrap();
        assert_eq!(p.bytes(), bytes);
    }
    assert!(MediaDatagram::copy_from(&[]).is_err());
    assert!(MediaDatagram::copy_from(&[0; 1233]).is_err());
}

#[cfg(feature = "hardware-host")]
mod assembly {
    use super::*;
    use std::alloc::{GlobalAlloc, Layout, System};
    use std::cell::Cell;
    thread_local! {static ACTIVE:Cell<bool>=const {Cell::new(false)};static EVENTS:Cell<usize>=const {Cell::new(0)};}
    struct Guard;
    unsafe impl GlobalAlloc for Guard {
        unsafe fn alloc(&self, l: Layout) -> *mut u8 {
            ACTIVE.with(|a| {
                if a.get() {
                    EVENTS.with(|n| n.set(n.get() + 1))
                }
            });
            unsafe { System.alloc(l) }
        }
        unsafe fn dealloc(&self, p: *mut u8, l: Layout) {
            ACTIVE.with(|a| {
                if a.get() {
                    EVENTS.with(|n| n.set(n.get() + 1))
                }
            });
            unsafe { System.dealloc(p, l) }
        }
    }
    #[global_allocator]
    static ALLOC: Guard = Guard;
    #[test]
    #[ignore = "requires verified actual SHR FX library via GP_FX_LIBRARY"]
    fn actual_aux_commits_refusals_and_gaps_do_not_allocate_or_destroy() {
        use gigpies::remote::fx_aux_owner::{
            self as owner, BrainAux, Command, Configuration, Message,
        };
        use gigpies::show::Counter;
        use sha2::{Digest, Sha256};
        let path = std::path::PathBuf::from(std::env::var_os("GP_FX_LIBRARY").unwrap());
        let hash = gigpies::hash::hex(Sha256::digest(std::fs::read(&path).unwrap()));
        let mut streams =
            grouped_streams(MediaRole::FxSend, &owner::channel_ids(), 48, 0, 1, 1232).unwrap();
        streams.extend(
            grouped_streams(
                MediaRole::WetReturn,
                &owner::channel_ids(),
                48,
                768,
                10,
                1232,
            )
            .unwrap(),
        );
        let descriptor = MediaDescriptor {
            session: Counter(1),
            source_epoch: Counter(2),
            capability_generation: Counter(3),
            map_generation: Counter(4),
            sample_rate: 48000,
            streams,
        };
        let mut brain = BrainAux::load(descriptor.clone(), &path, &hash, 16).unwrap();
        let mut output = [0.; 384];
        brain.process(0, &[0.25; 384], &mut output).unwrap();
        let mut next = 48;
        for (ticket, mode) in [
            (1, "sends"),
            (2, "settings"),
            (3, "unpermitted"),
            (4, "gap"),
            (5, "transition_gap"),
            (6, "panic"),
        ] {
            let before = brain.observation().unwrap();
            let mut config: Configuration =
                serde_json::from_str(&before.buses[0].configuration_json).unwrap();
            config.sends[0] = 0.25;
            if mode != "sends" {
                config.settings.time_ms = 3.0 + ticket as f64;
            }
            let frame = next + 48;
            let mutation = gigpies::fx_aux_wire::Mutation {
                bus: 0,
                map_revision: descriptor.map_generation,
                library_sha256: hash.clone(),
                expected_generation: before.buses[0].generation,
                configuration_json: (mode != "panic")
                    .then(|| serde_json::to_string(&config).unwrap()),
                panic: mode == "panic",
                owner_binding: Some(owner::binding(&descriptor, &hash).unwrap()),
            };
            assert!(matches!(
                brain
                    .command(Command::Prepare {
                        ticket: Counter(ticket),
                        descriptor: descriptor.clone(),
                        mutation: mutation.clone(),
                        apply_frame: Counter(frame),
                    })
                    .unwrap(),
                Some(Message::Prepared { .. })
            ));
            if mode != "unpermitted" {
                brain
                    .command(Command::Permit {
                        ticket: Counter(ticket),
                        descriptor: descriptor.clone(),
                        apply_frame: Counter(frame),
                    })
                    .unwrap();
            }
            EVENTS.with(|n| n.set(0));
            ACTIVE.with(|a| a.set(true));
            brain.process(next, &[0.25; 384], &mut output).unwrap();
            let boundary = if mode == "gap" { frame + 48 } else { frame };
            brain.process(boundary, &[0.25; 384], &mut output).unwrap();
            // Keep control stalled through the owner's entire transition. Old
            // configuration and owner storage must remain retained, never freed.
            for n in 1..=24 {
                let gap = u64::from(mode == "transition_gap");
                brain
                    .process(boundary + (n + gap) * 48, &[0.25; 384], &mut output)
                    .unwrap();
            }
            ACTIVE.with(|a| a.set(false));
            assert_eq!(EVENTS.with(Cell::get), 0, "{mode}");
            next = boundary + (25 + u64::from(mode == "transition_gap")) * 48;
            // The retirement/completion slot stays occupied until controller poll.
            assert!(matches!(
                brain
                    .command(Command::Prepare {
                        ticket: Counter(99),
                        descriptor: descriptor.clone(),
                        mutation,
                        apply_frame: Counter(next + 48),
                    })
                    .unwrap(),
                Some(Message::Refused { .. })
            ));
            let outcome = brain.poll().unwrap();
            if matches!(mode, "unpermitted" | "gap" | "transition_gap") {
                assert!(matches!(outcome, Some(Message::Refused { .. })));
            } else {
                assert!(matches!(outcome, Some(Message::Completed { .. })));
                let after = brain.observation().unwrap();
                assert_eq!(
                    after.buses[0].generation.0,
                    before.buses[0].generation.0 + 1
                );
                assert_eq!(after.buses[0].generation, after.buses[0].applied_generation);
            }
        }
        EVENTS.with(|n| n.set(0));
        ACTIVE.with(|a| a.set(true));
        assert!(brain.process(next, &[], &mut output).is_err());
        assert!(brain.process(u64::MAX, &[0.; 384], &mut output).is_err());
        ACTIVE.with(|a| a.set(false));
        assert_eq!(EVENTS.with(Cell::get), 0);
    }
    #[test]
    fn assembly_completion_overflow_and_refusal_never_allocate_or_destroy() {
        let mut streams = grouped_streams(
            MediaRole::FxSend,
            &["left".into(), "right".into()],
            48,
            0,
            1,
            240,
        )
        .unwrap();
        streams.extend(
            grouped_streams(
                MediaRole::WetReturn,
                &["left".into(), "right".into()],
                48,
                768,
                3,
                240,
            )
            .unwrap(),
        );
        let d = MediaDescriptor {
            session: gigpies::show::Counter(1),
            source_epoch: gigpies::show::Counter(2),
            capability_generation: gigpies::show::Counter(3),
            map_generation: gigpies::show::Counter(4),
            sample_rate: 48000,
            streams,
        };
        let a = d.streams[0].spec(1).unwrap();
        let b = d.streams[1].spec(1).unwrap();
        let mut receiver = GroupedReceiver::new(d, MediaRole::FxSend).unwrap();
        let storage = receiver.prepared_storage();
        assert!(storage.heap_bytes > 32 * 96 * 8);
        assert_eq!(
            storage.total_bytes,
            storage.inline_bytes + storage.heap_bytes
        );
        let mut output = [0.; 96];
        let mut bytes = [0; MAX_DATAGRAM];
        EVENTS.with(|n| n.set(0));
        ACTIVE.with(|a| a.set(true));
        for i in 0..33 {
            let n = a
                .encode_float(i * 48, i as u32, &[0.25; 48], &mut bytes)
                .unwrap();
            assert_eq!(
                receiver.push_into(Packet::parse(&bytes[..n]).unwrap(), &mut output),
                Ok(None)
            );
        }
        assert_eq!(receiver.incomplete_dropped, 1);
        let n = a
            .encode_float(32 * 48, 32, &[0.25; 48], &mut bytes)
            .unwrap();
        assert!(
            receiver
                .push_into(Packet::parse(&bytes[..n]).unwrap(), &mut output)
                .is_err()
        );
        let n = b
            .encode_float(32 * 48, 32, &[-0.5; 48], &mut bytes)
            .unwrap();
        assert_eq!(
            receiver.push_into(Packet::parse(&bytes[..n]).unwrap(), &mut output),
            Ok(Some(32 * 48))
        );
        assert_eq!(receiver.incomplete_dropped, 32);
        assert!(
            receiver
                .push_into(Packet::parse(&bytes[..n]).unwrap(), &mut output)
                .is_err()
        );
        assert!(
            receiver
                .push_into(Packet::parse(&bytes[..n]).unwrap(), &mut [])
                .is_err()
        );
        ACTIVE.with(|a| a.set(false));
        assert_eq!(EVENTS.with(Cell::get), 0);
        for pair in output.chunks_exact(2) {
            assert_eq!(pair, &[0.25, -0.5]);
        }
    }
}
